+func newTransactionalReloadState(path string, enabled bool, logger *slog.Logger) *transactionalReloadState {
+	s := &transactionalReloadState{enabled: enabled, path: path, logger: logger, status: emptyReloadStatus()}
+	if !enabled {
+		return s
+	}
+	b, err := os.ReadFile(path)
