+func emptyReloadStatus() api_v1.ReloadStatus {
+	return api_v1.ReloadStatus{ErrorCategory: "none", AppliedReloaders: []string{}, ReloaderTimingsMS: map[string]float64{}}
+}
+
+func (s *transactionalReloadState) Status() api_v1.ReloadStatus {
+	s.mu.RLock()
+	defer s.mu.RUnlock()
+	r := s.status
+	r.AppliedReloaders = append([]string{}, r.AppliedReloaders...)
+	r.ReloaderTimingsMS = mapsClone(r.ReloaderTimingsMS)
+	return r
+}
+
+func mapsClone(in map[string]float64) map[string]float64 {
+	out := make(map[string]float64, len(in))
+	for k, v := range in { out[k] = v }
+	return out
+}
+
+func (s *transactionalReloadState) SetKnownGoodFromFile(filename string, enableExemplarStorage bool) {
+	if !s.enabled { return }
+	conf, err := config.LoadFile(filename, agentMode, s.logger)
+	if err != nil { s.logger.Warn("Unable to retain initial configuration for transactional reload", "err", err); return }
+	if enableExemplarStorage && conf.StorageConfig.ExemplarsConfig == nil { conf.StorageConfig.ExemplarsConfig = &config.DefaultExemplarsConfig }
+	s.mu.Lock()
+	s.knownGood = conf
+	s.mu.Unlock()
+}
+
+func (s *transactionalReloadState) record(status api_v1.ReloadStatus) {
+	s.mu.Lock()
+	s.status = status
+	s.mu.Unlock()
+	b, err := json.Marshal(status)
+	if err != nil { s.logger.Warn("Unable to encode transactional reload status", "err", err); return }
+	if err := os.MkdirAll(filepath.Dir(s.path), 0o755); err != nil { s.logger.Warn("Unable to create transactional reload status directory", "err", err); return }
+	if err := os.WriteFile(s.path, b, 0o644); err != nil { s.logger.Warn("Unable to persist transactional reload status", "err", err) }
+}
+
+func reloadConfigWithMode(filename string, enableExemplarStorage bool, logger *slog.Logger, noStepSubqueryInterval *safePromQLNoStepSubqueryInterval, callback func(bool), state *transactionalReloadState, rls ...reloader) error {
+	if !state.enabled { return reloadConfig(filename, enableExemplarStorage, logger, noStepSubqueryInterval, callback, rls...) }
+	return reloadConfigTransactional(filename, enableExemplarStorage, logger, noStepSubqueryInterval, callback, state, rls...)
+}
+
+func reloadConfigTransactional(filename string, enableExemplarStorage bool, logger *slog.Logger, noStepSubqueryInterval *safePromQLNoStepSubqueryInterval, callback func(bool), state *transactionalReloadState, rls ...reloader) (err error) {
+	outcome := emptyReloadStatus()
+	outcome.LastReloadID = time.Now().UTC().Format(time.RFC3339)
+	defer func() {
+		outcome.LastReloadSuccessful = err == nil
+		state.record(outcome)
+		if err == nil { configSuccess.Set(1); configSuccessTime.SetToCurrentTime(); callback(true) } else { configSuccess.Set(0); callback(false) }
+	}()
+	conf, err := config.LoadFile(filename, agentMode, logger)
+	if err != nil {
+		outcome.ErrorCategory, outcome.ErrorMessage = "load_error", err.Error()
+		return fmt.Errorf("couldn't load configuration (--config.file=%q): %w", filename, err)
+	}
+	if enableExemplarStorage && conf.StorageConfig.ExemplarsConfig == nil { conf.StorageConfig.ExemplarsConfig = &config.DefaultExemplarsConfig }
+	for _, rl := range rls {
+		started := time.Now()
+		err := rl.reloader(conf)
+		outcome.ReloaderTimingsMS[rl.name] = float64(time.Since(started)) / float64(time.Millisecond)
+		if err != nil {
+			outcome.ErrorCategory, outcome.ErrorMessage, outcome.FailedReloader = "apply_error", err.Error(), rl.name
+			if len(outcome.AppliedReloaders) > 0 { rollbackTransactional(state, &outcome, rls) }
+			return fmt.Errorf("failed to apply configuration with reloader %q: %w", rl.name, err)
+		}
+		outcome.AppliedReloaders = append(outcome.AppliedReloaders, rl.name)
+	}
+	updateGoGC(conf, logger)
+	noStepSubqueryInterval.Set(conf.GlobalConfig.EvaluationInterval)
+	state.mu.Lock(); state.knownGood = conf; state.mu.Unlock()
+	return nil
+}
+
+func rollbackTransactional(state *transactionalReloadState, outcome *api_v1.ReloadStatus, rls []reloader) {
+	outcome.RollbackAttempted = true
+	state.mu.RLock(); previous := state.knownGood; state.mu.RUnlock()
+	if previous == nil { outcome.RollbackSuccessful = false; outcome.ErrorCategory = "rollback_error"; outcome.ErrorMessage = "no last known-good configuration available"; return }
+	for _, rl := range rls {
+		if err := rl.reloader(previous); err != nil { outcome.RollbackSuccessful = false; outcome.ErrorCategory = "rollback_error"; outcome.ErrorMessage = err.Error(); return }
+	}
+	outcome.RollbackSuccessful = true
+}
