func TestTransactionalReloadConfig(t *testing.T) {
	dir := t.TempDir()
	configFile := filepath.Join(dir, "prometheus.yml")
	require.NoError(t, os.WriteFile(configFile, []byte("global:\n  scrape_interval: 15s\n"), 0o644))
	state := newTransactionalReloadState(filepath.Join(dir, "reload-status.json"), true, promslog.NewNopLogger())
	state.SetKnownGoodFromFile(configFile, false)

	var applied []string
	reloaders := []reloader{
		{name: "first", reloader: func(*config.Config) error { applied = append(applied, "first"); return nil }},
		{name: "second", reloader: func(*config.Config) error { return errors.New("apply failed") }},
	}
	interval := &safePromQLNoStepSubqueryInterval{}
	err := reloadConfigTransactional(configFile, false, promslog.NewNopLogger(), interval, func(bool) {}, state, reloaders...)
	require.Error(t, err)
	require.Equal(t, []string{"first", "first"}, applied, "the previous configuration must be applied during rollback")
	status := state.Status()
	require.False(t, status.LastReloadSuccessful)
	require.Equal(t, "apply_error", status.ErrorCategory)
	require.Equal(t, "second", status.FailedReloader)
	require.Equal(t, []string{"first"}, status.AppliedReloaders)
	require.True(t, status.RollbackAttempted)
	require.True(t, status.RollbackSuccessful)
	require.FileExists(t, filepath.Join(dir, "reload-status.json"))

	applied = nil
	err = reloadConfigTransactional(filepath.Join(dir, "missing.yml"), false, promslog.NewNopLogger(), interval, func(bool) {}, state, reloaders...)
	require.Error(t, err)
	status = state.Status()
	require.Equal(t, "load_error", status.ErrorCategory)
	require.False(t, status.RollbackAttempted)
	require.Empty(t, applied)
}

